<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { ImagePlus, LoaderCircle, X } from 'lucide-vue-next'
import Modal from './Modal.vue'
import { api, isArchived, messageOf, notify, recordTypes, ui } from '../api'
import type { Attachment } from '../types'
const props=defineProps<{open:boolean;projectId?:string}>()
const emit=defineEmits<{close:[];saved:[]}>()
const initial=()=>({project_id:props.projectId||'',type:'note',title:'',content:'',location:'',tags:''})
const form=reactive(initial()); const attachments=ref<Attachment[]>([]); const saving=ref(false); const uploading=ref(0);const error=ref(''); const fileInput=ref<HTMLInputElement>()
const writableProjects=computed(()=>ui.projects.filter(p=>p.status!=='archived'))
watch(()=>props.open,(open)=>{if(open){Object.assign(form,initial());attachments.value=[];error.value=''}})
async function upload(files:File[]) { for(const file of files){if(attachments.value.length+uploading.value>=9){error.value='每条记录最多添加 9 张图片';continue}if(!['image/png','image/jpeg','image/gif'].includes(file.type)){error.value='请选择 PNG、JPEG 或 GIF 图片';continue} if(file.size>20*1024*1024){error.value='每张图片不得超过 20 MB';continue} uploading.value++; try { const data=new FormData(); data.set('file',file); const attachment=await api<Attachment>('/api/attachments',{method:'POST',body:data}); attachments.value.push(attachment) }catch(e){error.value=messageOf(e)}finally{uploading.value--} } }
function choose(event:Event){const target=event.target as HTMLInputElement;if(target.files)void upload(Array.from(target.files));target.value=''}
function paste(event:ClipboardEvent){const files=Array.from(event.clipboardData?.files||[]).filter(file=>file.type.startsWith('image/'));if(files.length){event.preventDefault();void upload(files)}}
function keydown(event:KeyboardEvent){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&((event.target as HTMLElement).tagName==='TEXTAREA')){event.preventDefault();void save()}}
function hasDraft(){return props.open&&!!(form.content.trim()||form.title.trim()||form.location.trim()||form.tags.trim()||attachments.value.length||uploading.value)}
function requestClose(){if(saving.value||uploading.value)return;if(hasDraft()&&!window.confirm('这条记录尚未保存，确定关闭并放弃本次内容？'))return;emit('close')}
function beforeUnload(event:BeforeUnloadEvent){if(hasDraft()){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload))
async function save(){if(saving.value||uploading.value)return;if(!form.content.trim()&&!form.title.trim()&&!attachments.value.length){error.value='写下记录内容或添加图片后再保存';return}if(isArchived(form.project_id)){error.value='归档项目不可新增记录';return}saving.value=true;error.value='';try{await api('/api/records',{method:'POST',body:JSON.stringify({...form,tags:form.tags.split(/[,，\s]+/).filter(Boolean),attachments:attachments.value})});notify('记录已保存');emit('saved');emit('close')}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
</script>
<template><Modal :open="open" title="记下现场的事" wide @close="requestClose"><form class="modal-body" @submit.prevent="save"><div class="form-row"><label>关联项目<select v-model="form.project_id"><option value="">未归类，稍后整理</option><option v-for="p in writableProjects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>记录类型<select v-model="form.type"><option v-for="(name,key) in recordTypes" :key="key" :value="key">{{name}}</option></select></label></div><label>标题 <span class="muted">选填</span><input v-model="form.title" maxlength="200" placeholder="用一句话概括"/></label><label>记录内容<textarea v-model="form.content" autofocus rows="7" placeholder="发生了什么？有什么结论或需要跟进的事？" @paste="paste" @keydown="keydown"/></label><p class="input-hint">Enter 保存，Shift + Enter 换行；支持粘贴截图，最多 9 张，每张 20 MB。</p><div class="upload-strip"><button type="button" class="button subtle small" :disabled="uploading>0" @click="fileInput?.click()"><LoaderCircle v-if="uploading" class="spin" :size="16"/><ImagePlus v-else :size="16"/>{{uploading?'正在上传…':'添加图片'}}</button><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/gif" multiple hidden @change="choose"/><div v-for="(a,index) in attachments" :key="a.id" class="uploaded-image"><img :src="a.url||`/api/attachments/${a.id}`" :alt="a.filename"/><button type="button" :aria-label="`移除图片 ${a.filename}`" @click="attachments.splice(index,1)"><X :size="12"/></button></div></div><div class="form-row"><label>位置 <span class="muted">选填</span><input v-model="form.location" placeholder="例如：主厂房二层" maxlength="200"/></label><label>标签 <span class="muted">空格或逗号分隔</span><input v-model="form.tags" placeholder="验收 设备安全"/></label></div><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-footer"><span class="muted">保存到本机工作空间</span><button type="submit" class="button primary" :disabled="saving||uploading>0">{{saving?'正在保存…':'保存记录'}}</button></div></form></Modal></template>
